// src/data/countries.ts
// Auto-generated static country -> currency data, curated from the
// \'world-countries\' npm package (dist/countries.json, v5.1.0) rather than
// hand-typed, so the ~247 entries below reflect real ISO country/currency
// pairings instead of a short hand-picked list.
//
// A handful of edits were made on top of the raw package data:
//  - Antarctica / Bouvet Island / Heard & McDonald Islands are excluded
//    outright (uninhabited, no currency of their own).
//  - Micronesia has no currency listed upstream; it genuinely uses USD,
//    so that was filled in manually.
//  - A few multi-currency countries (e.g. Cook Islands, Panama, Palestine,
//    Zimbabwe) had their primary currency corrected to the one actually
//    used day-to-day, since the source JSON key order is not meaningful.
// India is pinned first since it is this app default currency; the rest
// are alphabetical by country name.

export interface CountryOption {
  code: string; // ISO 3166-1 alpha-2
  name: string;
  currency: string; // ISO 4217
  symbol: string;
  flag: string;
}

